function hasNativeKeyword(card?: Card, keyword?: 'blocker' | 'rush' | 'double-attack' | 'banish' | 'trigger'): boolean {
  if (!card?.effect || !keyword) return false;
  if (String(card.type) === 'Event' || String(card.type) === 'Stage') {
    if (keyword !== 'trigger') return false;
  }
  const kwPattern = keyword.replace('-', '\\s+');
  const kwRegex = new RegExp(`\\[\\s*${kwPattern}\\s*\\]`, 'i');
  if (!kwRegex.test(card.effect)) return false;

  const cleaned = card.effect
    .replace(new RegExp(`(?:gains?|gives?|giving|without|with(?: a)?|activate(?:s)?|have|has)\\s+\\[${kwPattern}\\]`, 'gi'), '')
    .replace(new RegExp(`\\[${kwPattern}\\]\\s+(?:cards?|Characters?)`, 'gi'), '')
    .replace(new RegExp(`(?:cards?|Characters?)\\s+with\\s+(?:a\\s+)?\\[${kwPattern}\\]`, 'gi'), '');

  return new RegExp(`(?:^|\\n|\\]|\\.)\\s*\\[${kwPattern}\\]`, 'i').test(cleaned);
}
